//! Canonical `const` (P3): the value of a constant expression is a single object,
//! by structural value (specification §17.3 "Constants": two constant
//! expressions with the same value denote the same object, so
//! `identical(const C(1), const C(1))` is true).
//!
//! The key of a constant is its structural value, written as text
//! (`o:<constructor>(<args>)`, `l:[…]`, `i:1`…). Each key has a lazy
//! global `dfc.<hash>` with the getter `dfc.<hash>.get`, generated by whoever
//! uses it first; the getter evaluates the expression once and marks the collections
//! as immutable. An expression without a key (an argument the lowering cannot
//! evaluate as a constant) is lowered as before, without canonicalization.

use super::fn_builder::FnBuilder;
use crate::hir::*;
use dartforge_elements::model::Element;
use dartforge_frontend::ast::{
    self, CollectionElement, CreationKeyword, ExprId, ExprKind, UnaryOp,
};
use dartforge_types::resolved::{MemberRef, Resolved};
use dartforge_types::table::{Type as DartType, TypeId};

#[cfg(test)]
mod cache_failure_tests;

impl<'a, 'c> FnBuilder<'a, 'c> {
    /// Name of a `#x` literal; private names carry the identity of the
    /// library and use a hexadecimal suffix, like the VM's mangled name.
    pub fn symbol_literal_name(&self, names: &[ast::Name]) -> String {
        let mut name = names
            .iter()
            .map(|n| self.ctx.symbol_name(n.sym))
            .collect::<Vec<_>>()
            .join(".");
        if name.starts_with('_') {
            let lib = self.ctx.program.unit(self.unit_id).library;
            let uri = &self.ctx.program.library(lib).uri;
            name.push_str(&format!("@{:016x}", super::closures::hash_name(uri) as u64));
        }
        name
    }

    /// The structural key of the constant expression `e` (`in_const`: inside
    /// a constant context, where `C(…)` and `[…]` are implicitly const).
    pub fn constant_key(&self, ast: &ast::Ast, e: ExprId, in_const: bool) -> Option<String> {
        let expr = ast.expr(e);
        match &expr.kind {
            ExprKind::Int(s) => {
                let t = self.source()[s.start..s.end].replace('_', "");
                let v: i64 = if let Some(h) = t.strip_prefix("0x").or_else(|| t.strip_prefix("0X"))
                {
                    u64::from_str_radix(h, 16).ok()? as i64
                } else {
                    // See `lower_expr`: the literal is read as a `u64`.
                    t.parse::<u64>().ok()? as i64
                };
                Some(format!("i:{v}"))
            }
            ExprKind::Double(s) => {
                let t = self.source()[s.start..s.end].replace('_', "");
                let v: f64 = t.parse().ok()?;
                Some(format!("d:{}", v.to_bits()))
            }
            ExprKind::Bool(b) => Some(format!("b:{b}")),
            ExprKind::Null => Some("n".to_string()),
            ExprKind::Symbol(names) => {
                let name = self.symbol_literal_name(names);
                Some(format!("sym:{name:?}"))
            }
            ExprKind::String(s) => {
                let v = s.constant_value()?;
                Some(format!("s:{:?}", String::from_utf8_lossy(v.as_bytes())))
            }
            ExprKind::Parenthesized(x) => self.constant_key(ast, *x, in_const),
            ExprKind::Unary {
                op: UnaryOp::Neg,
                operand,
            } => {
                let k = self.constant_key(ast, *operand, in_const)?;
                Some(format!("neg({k})"))
            }
            ExprKind::Identifier(n) if self.local_const_keys.contains_key(&n.sym) => {
                self.local_const_keys.get(&n.sym).map(|(k, _)| k.clone())
            }
            ExprKind::Binary { op, left, right } => {
                let a = self.constant_key(ast, *left, true)?;
                let b = self.constant_key(ast, *right, true)?;
                let int = |k: &str| k.strip_prefix("i:").and_then(|v| v.parse::<i64>().ok());
                match (op, int(&a), int(&b)) {
                    (ast::BinaryOp::Add, Some(x), Some(y)) => {
                        Some(format!("i:{}", x.wrapping_add(y)))
                    }
                    (ast::BinaryOp::Sub, Some(x), Some(y)) => {
                        Some(format!("i:{}", x.wrapping_sub(y)))
                    }
                    (ast::BinaryOp::Mul, Some(x), Some(y)) => {
                        Some(format!("i:{}", x.wrapping_mul(y)))
                    }
                    (ast::BinaryOp::Add, None, None)
                        if a.starts_with("s:") && b.starts_with("s:") =>
                    {
                        // Two constant strings: the concatenated text.
                        let ta: String = serde_string(&a)?;
                        let tb: String = serde_string(&b)?;
                        Some(format!("s:{:?}", ta + &tb))
                    }
                    _ => None,
                }
            }
            ExprKind::Identifier(_) | ExprKind::Property { .. } => {
                // The tear-off of a top-level or static function is a constant
                // (`const F(main)`): the same key for the same function.
                let tearoff = match self.ctx.get_resolved(self.unit_id, e) {
                    Some(Resolved::Element(Element::Function(f))) => Some(f.0 as usize),
                    Some(Resolved::Member {
                        member: MemberRef::Function(f),
                        ..
                    }) if self.ctx.program.functions[f.0 as usize].static_ => Some(f.0 as usize),
                    _ => None,
                };
                if let Some(fid) = tearoff {
                    let f = &self.ctx.program.functions[fid];
                    if f.variable.is_none()
                        && f.kind == dartforge_elements::model::FunctionKind::Function
                        && self.ctx.bodies.units[self.unit_id.0 as usize]
                            .tearoff_instantiation(e)
                            .is_none()
                    {
                        return Some(format!("t:{}", super::symbol_of(self.ctx, fid)));
                    }
                }
                let vid = match self.ctx.get_resolved(self.unit_id, e) {
                    Some(Resolved::Element(Element::Variable(v))) => *v,
                    Some(Resolved::Element(Element::Function(f))) => {
                        self.ctx.program.functions[f.0 as usize].variable?
                    }
                    Some(Resolved::Member {
                        member: MemberRef::Variable(v),
                        ..
                    }) => *v,
                    Some(Resolved::Member {
                        member: MemberRef::Function(f),
                        ..
                    }) => self.ctx.program.functions[f.0 as usize].variable?,
                    _ => return None,
                };
                let var = &self.ctx.program.variables[vid.0 as usize];
                let enum_ = matches!(
                    var.node,
                    dartforge_elements::model::VariableRef::EnumConstant { .. }
                );
                if !(var.const_ || enum_) {
                    return None;
                }
                if let Some(k) = self.primitive_const_key(vid) {
                    return Some(k);
                }
                // String constants also need their scalar identity when a native
                // environment query is used through an imported alias.
                if var.const_
                    && self.ctx.get_type(self.unit_id, e) == Some(self.ctx.core.string)
                    && let Some(init) = self.variable_initializer_in(vid)
                {
                    let unit = match var.node {
                        dartforge_elements::model::VariableRef::Field { unit, .. }
                        | dartforge_elements::model::VariableRef::TopLevel { unit, .. } => {
                            Some(unit)
                        }
                        _ => None,
                    };
                    if let Some(unit) = unit {
                        let other =
                            FnBuilder::new(self.ctx, unit, String::new(), String::new(), Type::Ref);
                        if let Some(key) =
                            other.constant_key(&self.ctx.program.unit(unit).ast, init, true)
                            && key.starts_with("s:")
                        {
                            return Some(key);
                        }
                    }
                }
                let library = self.ctx.library_name(var.library);
                let owner = if let Some(cid) = var.class {
                    format!(
                        ".{}",
                        self.ctx.symbol_name(self.ctx.program.class(cid).name)
                    )
                } else if let Some(eid) = var.extension {
                    let name_str = self.ctx.program.extension(eid).name?;
                    format!(".{}", self.ctx.symbol_name(name_str))
                } else {
                    String::new()
                };
                Some(format!(
                    "g:{:?}",
                    (library, owner, self.ctx.symbol_name(var.name))
                ))
            }
            ExprKind::InstanceCreation {
                keyword, arguments, ..
            } => {
                let in_const = in_const || *keyword == Some(CreationKeyword::Const);
                if !in_const {
                    return None;
                }
                let Some(Resolved::Constructor(f)) = self.ctx.get_resolved(self.unit_id, e) else {
                    return None;
                };
                self.creation_key(ast, e, f.0 as usize, arguments)
            }
            ExprKind::Call { arguments, .. } if in_const => {
                let Some(Resolved::Constructor(f)) = self.ctx.get_resolved(self.unit_id, e) else {
                    return None;
                };
                self.creation_key(ast, e, f.0 as usize, arguments)
            }
            ExprKind::List {
                const_, elements, ..
            } => {
                if !(in_const || *const_) {
                    return None;
                }
                let parts = self.elements_parts(ast, elements, false)?;
                Some(format!("l{}:[{}]", self.type_in_key(e)?, parts.join(",")))
            }
            ExprKind::SetOrMap {
                const_, elements, ..
            } => {
                if !(in_const || *const_) {
                    return None;
                }
                let set = self.literal_is_set(e, elements);
                let parts = self.elements_parts(ast, elements, !set)?;
                Some(format!(
                    "{}{}:{{{}}}",
                    if set { "c" } else { "m" },
                    self.type_in_key(e)?,
                    parts.join(",")
                ))
            }
            ExprKind::Record {
                positional, named, ..
            } if in_const => {
                let mut parts = Vec::new();
                for x in positional.iter() {
                    parts.push(self.constant_key(ast, *x, true)?);
                }
                let mut named_args: Vec<(String, String)> = Vec::new();
                for (n, x) in named.iter() {
                    named_args.push((
                        self.ctx.symbol_name(n.sym).to_string(),
                        self.constant_key(ast, *x, true)?,
                    ));
                }
                named_args.sort();
                for (n, k) in named_args {
                    parts.push(format!("{n}={k}"));
                }
                Some(format!("r:({})", parts.join(",")))
            }
            _ => None,
        }
    }

    /// The keys of the elements of a constant collection, in order: the
    /// spreads of another constant collection come in element by element and
    /// an `if` with a constant condition through the chosen branch (`const [...a, 3]` is
    /// the same constant as `const [1, 2, 3]`). `map`: `k=>v` entries.
    fn elements_parts(
        &self,
        ast: &ast::Ast,
        elements: &[CollectionElement],
        map: bool,
    ) -> Option<Vec<String>> {
        let mut parts = Vec::new();
        for el in elements {
            self.element_parts(ast, el, map, &mut parts)?;
        }
        Some(parts)
    }

    fn element_parts(
        &self,
        ast: &ast::Ast,
        el: &CollectionElement,
        map: bool,
        parts: &mut Vec<String>,
    ) -> Option<()> {
        match el {
            CollectionElement::Expression(x) if !map => {
                parts.push(self.constant_key(ast, *x, true)?)
            }
            CollectionElement::MapEntry {
                key,
                value,
                null_aware_key: false,
                null_aware_value: false,
            } if map => {
                let k = self.constant_key(ast, *key, true)?;
                let v = self.constant_key(ast, *value, true)?;
                parts.push(format!("{k}=>{v}"));
            }
            CollectionElement::Spread { value, null_aware } => {
                if *null_aware && self.constant_key(ast, *value, true).as_deref() == Some("n") {
                    return Some(());
                }
                parts.extend(self.spread_parts(ast, *value, map)?);
            }
            CollectionElement::If {
                condition,
                case_pattern: None,
                guard: None,
                then,
                else_,
            } => {
                // A constant of another declared type (`const dynamic yes =
                // true`) is a reference in the key: its value decides.
                let key = self.constant_key(ast, *condition, true)?;
                let truth = match key.as_str() {
                    "b:true" => true,
                    "b:false" => false,
                    _ => match self.ctx.get_resolved(self.unit_id, *condition) {
                        Some(Resolved::Element(Element::Variable(v))) => {
                            self.primitive_const_bool(*v)?
                        }
                        Some(Resolved::Element(Element::Function(f))) => self
                            .primitive_const_bool(
                                self.ctx.program.functions[f.0 as usize].variable?,
                            )?,
                        _ => return None,
                    },
                };
                if truth {
                    self.element_parts(ast, then, map, parts)?;
                } else if let Some(e) = else_ {
                    self.element_parts(ast, e, map, parts)?;
                }
            }
            _ => return None,
        }
        Some(())
    }

    /// The elements (or entries) of the constant collection that `e` denotes: the
    /// literal, a local `const`, or a top-level/static `const` of this
    /// unit.
    fn spread_parts(&self, ast: &ast::Ast, e: ExprId, map: bool) -> Option<Vec<String>> {
        match &ast.expr(e).kind {
            ExprKind::Parenthesized(x) => self.spread_parts(ast, *x, map),
            ExprKind::List { elements, .. } if !map => self.elements_parts(ast, elements, false),
            ExprKind::SetOrMap { elements, .. } => {
                let set = self.literal_is_set(e, elements);
                if set == map {
                    return None;
                }
                self.elements_parts(ast, elements, map)
            }
            ExprKind::Identifier(n) if self.local_const_keys.contains_key(&n.sym) => {
                let (_, init) = self.local_const_keys.get(&n.sym)?;
                self.spread_parts(ast, *init, map)
            }
            ExprKind::Identifier(_) | ExprKind::Property { .. } => {
                let vid = match self.ctx.get_resolved(self.unit_id, e) {
                    Some(Resolved::Element(Element::Variable(v))) => *v,
                    Some(Resolved::Element(Element::Function(f))) => {
                        self.ctx.program.functions[f.0 as usize].variable?
                    }
                    Some(Resolved::Member {
                        member: MemberRef::Variable(v),
                        ..
                    }) => *v,
                    _ => return None,
                };
                let var = &self.ctx.program.variables[vid.0 as usize];
                if !var.const_ {
                    return None;
                }
                let unit_ref = match var.node {
                    dartforge_elements::model::VariableRef::Field { unit, .. }
                    | dartforge_elements::model::VariableRef::TopLevel { unit, .. } => unit,
                    _ => return None,
                };
                let init = self.variable_initializer_in(vid)?;
                if unit_ref == self.unit_id {
                    return self.spread_parts(ast, init, map);
                }
                // A `const` of another unit (another library or another
                // `part`): the initializer is an `ExprId` of *its* AST, read
                // with its resolutions and source. With the current AST, the
                // index pointed to another expression (the key came out wrong,
                // `identical` gave false) or outside the arena (panic).
                let other =
                    FnBuilder::new(self.ctx, unit_ref, String::new(), String::new(), Type::Ref);
                let ast_other = &self.ctx.program.unit(unit_ref).ast;
                other.spread_parts(ast_other, init, map)
            }
            _ => None,
        }
    }

    /// The static type in the key (`const <int>[]` and `const <String>[]` are
    /// different constants).
    fn type_in_key(&self, e: ExprId) -> Option<String> {
        self.ctx.get_type(self.unit_id, e).map_or_else(
            || Some(String::new()),
            |t| self.stable_type(t).map(|s| format!("<{s}>")),
        )
    }

    /// Structural identity of the type, without `TypeId`/`ClassId`/`SymbolId`, whose
    /// numbering depends on the order in which files are loaded and interned.
    /// If the type depends on a generic parameter, the expression gets no
    /// canonical getter until there is an identity independent of the instance.
    fn stable_type(&self, t: TypeId) -> Option<String> {
        let parts = |xs: &[TypeId]| -> Option<Vec<String>> {
            xs.iter().map(|&x| self.stable_type(x)).collect()
        };
        match self.ctx.table.get(t) {
            DartType::Dynamic => Some("dynamic".into()),
            DartType::Void => Some("void".into()),
            DartType::Never => Some("Never".into()),
            DartType::Null => Some("Null".into()),
            DartType::Interface {
                class,
                args,
                nullable,
            }
            | DartType::ExtensionType {
                decl: class,
                args,
                nullable,
            } => {
                let c = self.ctx.program.class(*class);
                let lib = self.ctx.library_name(c.library);
                Some(format!(
                    "{lib:?}.{}<{}>{nullable}",
                    self.ctx.symbol_name(c.name),
                    parts(args)?.join(",")
                ))
            }
            DartType::FutureOr { arg, nullable } => {
                Some(format!("FutureOr<{}>{nullable}", self.stable_type(*arg)?))
            }
            DartType::Record {
                positional,
                named,
                nullable,
            } => {
                let mut fields: Vec<_> = named
                    .iter()
                    .map(|(n, t)| {
                        Some((self.ctx.symbol_name(*n).to_owned(), self.stable_type(*t)?))
                    })
                    .collect::<Option<_>>()?;
                fields.sort();
                Some(format!(
                    "record({};{:?}){nullable}",
                    parts(positional)?.join(","),
                    fields
                ))
            }
            DartType::Function {
                type_params,
                ret,
                positional,
                optional,
                named,
                nullable,
            } if type_params.is_empty() => {
                let mut fields: Vec<_> = named
                    .iter()
                    .map(|(n, t, req)| {
                        Some((
                            self.ctx.symbol_name(*n).to_owned(),
                            self.stable_type(*t)?,
                            req,
                        ))
                    })
                    .collect::<Option<_>>()?;
                fields.sort();
                Some(format!(
                    "fn({};{};{:?})->{}{nullable}",
                    parts(positional)?.join(","),
                    parts(optional)?.join(","),
                    fields,
                    self.stable_type(*ret)?
                ))
            }
            DartType::Function { .. }
            | DartType::TypeParameter { .. }
            | DartType::Intersection { .. } => None,
        }
    }

    /// The key of `const C<…>(…)`: the constructor, the arguments and — in a
    /// generic class — the creation type: `const Link<Token>()` and `const
    /// Link<BeginToken>()` are distinct objects (the type arguments are
    /// part of the identity of the constant), otherwise the second would be the first,
    /// with the wrong reified type (the `groupingStack` of the analyzer's scanner).
    fn creation_key(
        &self,
        ast: &ast::Ast,
        e: ExprId,
        fid: usize,
        arguments: &ast::Arguments,
    ) -> Option<String> {
        if let Some((kind, has)) =
            self.environment_factory(dartforge_elements::model::FunctionElementId(fid as u32))
        {
            let key = arguments.args.iter().find(|a| a.name.is_none())?.value;
            self.environment_key(self.unit_id, key, 0)?;
            return match self.environment_value(self.unit_id, key, kind, has) {
                Some(Constant::Bool(value)) => Some(format!("b:{value}")),
                Some(Constant::String(value)) => Some(format!("s:{value:?}")),
                _ => {
                    if let Some(default) = arguments.args.iter().find(|a| {
                        a.name
                            .is_some_and(|n| self.ctx.symbol_name(n.sym) == "defaultValue")
                    }) {
                        self.constant_key(ast, default.value, true)
                    } else {
                        Some(
                            match kind {
                                "bool" => "b:false",
                                "int" => "i:0",
                                _ => "s:\"\"",
                            }
                            .to_string(),
                        )
                    }
                }
            };
        }
        if !super::user_function(self.ctx, fid) {
            return None;
        }
        if self.ctx.program.functions[fid].class == self.ctx.sdk_class("core", "Symbol") {
            let text = arguments
                .args
                .first()
                .and_then(|a| match &ast.expr(a.value).kind {
                    ExprKind::String(s) => s
                        .constant_value()
                        .map(|v| String::from_utf8_lossy(v.as_bytes()).into_owned()),
                    _ => None,
                })?;
            return Some(format!("sym:{text:?}"));
        }
        let mut pos = Vec::new();
        let mut named_args = Vec::new();
        for a in arguments.args.iter() {
            let k = self.constant_key(ast, a.value, true)?;
            match a.name {
                Some(n) => named_args.push((self.ctx.symbol_name(n.sym).to_string(), k)),
                None => pos.push(k),
            }
        }
        named_args.sort();
        for (n, k) in named_args {
            pos.push(format!("{n}={k}"));
        }
        let generic = self.ctx.program.functions[fid]
            .class
            .and_then(|c| self.ctx.outline.classes.get(c.0 as usize))
            .is_some_and(|d| !d.type_params.is_empty());
        let ty = if generic {
            self.type_in_key(e)?
        } else {
            String::new()
        };
        Some(format!(
            "o:{}{ty}({})",
            super::symbol_of(self.ctx, fid),
            pos.join(",")
        ))
    }

    /// If `e` is a canonical constant (`const`, a constant collection
    /// literal), its value through the canonical global; otherwise `None`.
    pub fn canonical_constant(&mut self, ast: &ast::Ast, e: ExprId) -> Option<Operand> {
        if self.constant_in_progress == Some(e) {
            return None;
        }
        let ctx_const = self.in_const_context;
        let explicit = match &ast.expr(e).kind {
            ExprKind::InstanceCreation { keyword, .. } => {
                ctx_const || *keyword == Some(CreationKeyword::Const)
            }
            ExprKind::Symbol(_) => true,
            ExprKind::List { const_, .. } | ExprKind::SetOrMap { const_, .. } => {
                ctx_const || *const_
            }
            ExprKind::Call { .. } | ExprKind::Record { .. } => ctx_const,
            _ => false,
        };
        if !explicit {
            return None;
        }
        let getter = self.constant_getter(ast, e)?;
        Some(self.emit_call_with_check(
            Instruction::CallStatic {
                symbol: getter,
                args: Vec::new(),
                ret_ty: Type::Ref,
            },
            Type::Ref,
        ))
    }

    /// The canonical getter (`dfc.<hash>.get`) of the constant expression `e`,
    /// created the first time, without calling it (the table of a large literal
    /// cites it, `literals.rs`); `None` without a key.
    pub fn constant_getter(&mut self, ast: &ast::Ast, e: ExprId) -> Option<String> {
        if self.constant_in_progress == Some(e) {
            return None;
        }
        let key = self.constant_key(ast, e, true)?;
        let hash = super::closures::hash_name(&key) as u64;
        let value_symbol = format!("dfc.{hash:016x}");
        let getter = format!("{value_symbol}.get");
        if !self.done_entries.contains(&getter) {
            self.done_entries.insert(getter.clone());
            if self.ctx.arc_memory {
                self.arc_shared_functions.insert(getter.clone());
                // The getter returns the constant like Dart functions: Owned.
                self.dart_ref_returns.insert(getter.clone());
            }
            let root = 0x4000_0000 | (hash as u32 & 0x3fff_ffff);
            self.extra_globals
                .push((root, Type::Ref, value_symbol.clone()));
            let mut g = FnBuilder::new(
                self.ctx,
                self.unit_id,
                getter.clone(),
                "const".to_string(),
                Type::Ref,
            );
            g.constant_in_progress = Some(e);
            g.in_const_context = true;
            // The local `const`s visible here (the getter is another function: it
            // evaluates them again, through the initializer, which is constant).
            g.local_const_keys = self.local_const_keys.clone();
            g.lower_constant_getter(ast, e, &value_symbol, root);
            self.extra_globals
                .extend(std::mem::take(&mut g.extra_globals));
            self.absorb(g);
        }
        Some(getter)
    }

    /// Body of the getter of a canonical constant.
    fn lower_constant_getter(&mut self, ast: &ast::Ast, e: ExprId, value: &str, root: u32) {
        // `const {…}` is a `_ConstMap`/`_ConstSet` (immutable, as in the VM),
        // built from the `_Map`/`_Set` of the literal.
        if let ExprKind::SetOrMap { elements, .. } = &ast.expr(e).kind {
            let set = self.literal_is_set(e, elements);
            let ty = self.ctx.get_type(self.unit_id, e);
            self.lower_canonical_getter(value, root, false, |b| {
                let source = b.lower_expr(ast, e);
                b.source_constant_collection(source, ty, set, ast.expr(e).span)
            });
            return;
        }
        let collection = matches!(
            ast.expr(e).kind,
            ExprKind::List { .. } | ExprKind::SetOrMap { .. }
        );
        self.lower_canonical_getter(value, root, collection, |b| b.lower_expr(ast, e));
    }

    /// The `_ConstMap<K, V>`/`_ConstSet<E>` that adopts the content of `source`
    /// (the `_Map`/`_Set` of the literal), with the type arguments of `ty`.
    fn source_constant_collection(
        &mut self,
        source: Operand,
        ty: Option<TypeId>,
        set: bool,
        span: dartforge_diagnostics::Span,
    ) -> Operand {
        let name_str = if set { "_ConstSet" } else { "_ConstMap" };
        let Some(cid) = self.ctx.sdk_class("_compact_hash", name_str) else {
            return self.unsupported(&format!("constant without `{name_str}`"), span);
        };
        let ctor = self.ctx.interner.lookup("_fromSource").and_then(|k| {
            self.ctx.program.classes[cid.0 as usize]
                .constructors
                .get(&k)
                .copied()
        });
        let Some(ctor) = ctor else {
            return self.unsupported(&format!("missing `{name_str}._fromSource`"), span);
        };
        let n = if set { 1 } else { 2 };
        let args: Vec<TypeId> = match ty.map(|t| self.ctx.table.get(t)) {
            Some(DartType::Interface { args, .. }) if args.len() == n => args.to_vec(),
            _ => vec![self.ctx.core.dynamic_; n],
        };
        let mut recipe = super::rti::Recipe {
            text: String::new(),
            variables: false,
        };
        for (i, a) in args.iter().enumerate() {
            if i > 0 {
                recipe.text.push(',');
            }
            let r = self.type_recipe(*a);
            recipe.text.push_str(&r.text);
            recipe.variables |= r.variables;
        }
        let object = self.recipe_rti(&super::rti::Recipe {
            text: format!("C{}<{}>", self.ctx.id_rti(cid), recipe.text),
            variables: recipe.variables,
        });
        let source = self.coerce(source, Type::Ref);
        self.instantiate_evaluated_with_rti(ctor, &[(None, source)], span, Some(object), None)
    }

    /// The canonical constant that `generate` produces, through the getter `value_symbol`
    /// + `.get` (created on the first read; `collection`: it becomes immutable).
    pub fn generated_constant(
        &mut self,
        value_symbol: &str,
        collection: bool,
        generate: impl FnOnce(&mut Self) -> Operand,
    ) -> Operand {
        let getter = format!("{value_symbol}.get");
        if !self.done_entries.contains(&getter) {
            self.done_entries.insert(getter.clone());
            if self.ctx.arc_memory {
                self.arc_shared_functions.insert(getter.clone());
                // The getter returns the constant like Dart functions: Owned.
                self.dart_ref_returns.insert(getter.clone());
            }
            let hash = super::closures::hash_name(value_symbol) as u64;
            let root = 0x4000_0000 | (hash as u32 & 0x3fff_ffff);
            self.extra_globals
                .push((root, Type::Ref, value_symbol.to_string()));
            let mut g = FnBuilder::new(
                self.ctx,
                self.unit_id,
                getter.clone(),
                "const".to_string(),
                Type::Ref,
            );
            g.in_const_context = true;
            g.lower_canonical_getter(value_symbol, root, collection, generate);
            self.extra_globals
                .extend(std::mem::take(&mut g.extra_globals));
            self.absorb(g);
        }
        self.emit_call_with_check(
            Instruction::CallStatic {
                symbol: getter,
                args: Vec::new(),
                ret_ty: Type::Ref,
            },
            Type::Ref,
        )
    }

    fn lower_canonical_getter(
        &mut self,
        value: &str,
        root: u32,
        collection: bool,
        generate: impl FnOnce(&mut Self) -> Operand,
    ) {
        let flag = format!("{value}$ok");
        let ok = self.emit(
            Instruction::LoadGlobal {
                symbol: flag.clone(),
                ty: Type::I8,
            },
            Type::I8,
        );
        let ready = self.emit(
            Instruction::ICmp(ICmpOp::Ne, ok, Operand::Constant(Constant::Int(0))),
            Type::I1,
        );
        let b_read = self.new_block();
        let b_init = self.new_block();
        self.terminate(Terminator::CondBranch {
            cond: ready,
            then_block: b_read,
            else_block: b_init,
        });
        self.set_block(b_read);
        let v = self.emit(
            Instruction::LoadGlobal {
                symbol: value.to_string(),
                ty: Type::Ref,
            },
            Type::Ref,
        );
        self.terminate(Terminator::Return(Some(v)));
        self.set_block(b_init);
        let v = generate(self);
        let v = self.coerce(v, Type::Ref);
        // The constant list becomes a NEW `_ImmutableList` (the class does not change
        // after publication, docs/NATIVO-ESPACO-UNIFICADO.md §2.16): the value
        // kept and returned is the one the runtime returns.
        let v = if collection {
            self.emit(
                Instruction::CallRuntime {
                    name: "dartforge_collection_mark_unmodifiable".to_string(),
                    args: vec![(v, Type::Ref)],
                    ret_ty: Type::Ref,
                },
                Type::Ref,
            )
        } else {
            // An assembled `String` (constant interpolation) becomes the canonical
            // literal with the same content; any other value comes back as it is.
            self.emit(
                Instruction::CallRuntime {
                    name: "dartforge_canonical_constant".to_string(),
                    args: vec![(v, Type::Ref)],
                    ret_ty: Type::Ref,
                },
                Type::Ref,
            )
        };
        self.emit(
            Instruction::StoreGlobal {
                symbol: value.to_string(),
                val: v.clone(),
                ty: Type::Ref,
                root: Some(root),
            },
            Type::Void,
        );
        self.emit(
            Instruction::CallRuntime {
                name: "dartforge_mark_constant".to_string(),
                args: vec![
                    (v.clone(), Type::Ref),
                    (
                        Operand::Constant(Constant::Function(self.func.symbol.clone())),
                        Type::I64,
                    ),
                ],
                ret_ty: Type::Void,
            },
            Type::Void,
        );
        self.emit(
            Instruction::StoreGlobal {
                symbol: flag,
                val: Operand::Constant(Constant::Int(1)),
                ty: Type::I8,
                root: None,
            },
            Type::Void,
        );
        self.terminate(Terminator::Return(Some(v)));
    }

    /// Lowers `e` in a constant context (a `const` initializer, a default
    /// parameter value).
    /// The text of the constant `String` that `e` denotes in a constant
    /// context, when its value is the canonical literal (see `lower_expr`): a
    /// concatenation, an interpolation or a `const` variable.
    pub(super) fn constant_string(&self, ast: &ast::Ast, e: ExprId) -> Option<String> {
        // Outside a constant context a `const` variable is read through its
        // getter, which marks the constant (its identity across isolates).
        let folds = matches!(
            &ast.expr(e).kind,
            ExprKind::Identifier(_)
                | ExprKind::Property { .. }
                | ExprKind::Binary { .. }
                | ExprKind::String(_)
        ) && self.in_const_context;
        if !folds || self.ctx.get_type(self.unit_id, e) != Some(self.ctx.core.string) {
            return None;
        }
        // A plain literal already is the canonical one.
        if let ExprKind::String(s) = &ast.expr(e).kind
            && s.constant_value().is_some()
        {
            return None;
        }
        serde_string(&self.constant_key(ast, e, true)?)
    }

    pub fn lower_in_const_context(&mut self, ast: &ast::Ast, e: ExprId) -> Operand {
        let saved = std::mem::replace(&mut self.in_const_context, true);
        let v = self.lower_expr(ast, e);
        self.in_const_context = saved;
        v
    }
}

/// The text of a key `s:"…"` (the `{:?}` of a `String`).
pub(super) fn serde_string(key: &str) -> Option<String> {
    let quotes = key.strip_prefix("s:")?;
    let inside = quotes.strip_prefix('"')?.strip_suffix('"')?;
    // Only the case without escapes: the rest is not canonicalized by text.
    (!inside.contains('\\')).then(|| inside.to_string())
}
